const config = $('Resolve Config').first().json;
const supabaseUrl = config.supabaseUrl;
const supabaseKey = config.supabaseKey;

const now = new Date();
const currentMonth = now.getMonth() + 1;

// Calculate ISO week number
const jan1 = new Date(now.getFullYear(), 0, 1);
const daysSinceJan1 = Math.floor((now.getTime() - jan1.getTime()) / 86400000);
const weekNumber = Math.ceil((daysSinceJan1 + jan1.getDay() + 1) / 7);
const year = now.getFullYear();

async function querySupabase(table, params = '') {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${supabaseUrl}/rest/v1/${table}${params}`,
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Content-Type': 'application/json'
      },
      json: true,
      timeout: 10000
    });
    return res;
  } catch (e) {
    return [];
  }
}

// Fetch seasonal produce for current month
const produce = await querySupabase.call(this, 'seasonal_produce', `?months_available=cs.{${currentMonth}}`);
const seasonalProduce = produce.map(p => ({ name: p.name, category: p.category }));

// Fetch traditions for current month
const traditions = await querySupabase.call(this, 'food_traditions', `?months=cs.{${currentMonth}}`);
const traditionsContext = traditions.map(t => ({
  name: t.name,
  country: t.country,
  period: `Maaned ${currentMonth}`,
  typicalDishes: t.typical_dishes || [],
  suggestStrength: t.suggest_strength,
  description: t.description || ''
}));

// Fetch family preferences
const prefs = await querySupabase.call(this, 'family_preferences', `?household_id=eq.default`);
const familyMap = {};
for (const p of prefs) {
  familyMap[p.key] = p.value;
}
const family = prefs.length > 0 ? {
  adults: familyMap.adults || 2,
  children: familyMap.children || 0,
  allergies: familyMap.allergies || [],
  dislikes: familyMap.dislikes || [],
  cuisinePreferences: familyMap.cuisinePreferences || []
} : undefined;

// Fetch pantry staples
const staples = await querySupabase.call(this, 'pantry_staples', `?household_id=eq.default`);
const pantryStaples = staples.map(s => s.name);

// Fetch nutrition knowledge
const knowledge = await querySupabase.call(this, 'nutrition_knowledge');
const nutritionGuidelines = knowledge.map(k => ({
  category: k.category,
  topic: k.topic,
  content: k.content,
  appliesTo: k.applies_to
}));

// Fetch recent planned meals (last 2 weeks)
const twoWeeksAgo = new Date(now.getTime() - 14 * 86400000).toISOString();
const recentPlans = await querySupabase.call(this, 'weekly_plans', `?created_at=gte.${twoWeeksAgo}&household_id=eq.default&select=id`);
let recentMeals = [];
if (recentPlans.length > 0) {
  const planIds = recentPlans.map(p => p.id).join(',');
  const meals = await querySupabase.call(this, 'planned_meals', `?plan_id=in.(${planIds})&select=name,day_of_week,feedback_emoji`);
  recentMeals = meals.map(m => ({
    name: m.name,
    dayOfWeek: m.day_of_week,
    feedbackEmoji: m.feedback_emoji
  }));
}

// Fetch inventory notes
const inventory = await querySupabase.call(this, 'inventory_notes', `?household_id=eq.default&status=in.(available,use_soon)`);
const inventoryNotes = inventory.map(i => ({
  itemName: i.item_name,
  status: i.status,
  quantity: i.quantity
}));

return [{
  json: {
    weekNumber,
    year,
    householdId: 'default',
    family,
    seasonalProduce,
    traditions: traditionsContext,
    recentMeals,
    nutritionGuidelines,
    pantryStaples,
    inventoryNotes
  }
}];

const context = $input.first().json;

const agentResponse = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://fyrk-agent-runtime.fly.dev/run/meal-plan',
  headers: { 'Content-Type': 'application/json' },
  body: {
    version: '0.1',
    input: context,
    dryRun: false,
    publish: true
  },
  json: true,
  timeout: 90000
});

return [{ json: agentResponse }];

const config = $('Resolve Config').first().json;
const data = $('Status OK?').first().json;
const output = data.output;
const supabaseUrl = config.supabaseUrl;
const supabaseKey = config.supabaseKey;

// Insert weekly plan
const planRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `${supabaseUrl}/rest/v1/weekly_plans`,
  headers: {
    'apikey': supabaseKey,
    'Authorization': `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  },
  body: {
    household_id: 'default',
    week_number: output.weekNumber,
    year: output.year,
    status: 'proposed',
    run_id: data.runId
  },
  json: true
});

const plan = Array.isArray(planRes) ? planRes[0] : planRes;

// Insert planned meals
if (plan && plan.id && output.meals.length > 0) {
  const mealsToInsert = output.meals.map(m => ({
    plan_id: plan.id,
    day_of_week: m.dayOfWeek,
    meal_type: 'dinner',
    name: m.name,
    description: m.description,
    estimated_prep_min: m.estimatedPrepMin,
    tags: m.tags
  }));

  await this.helpers.httpRequest({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/planned_meals`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    },
    body: mealsToInsert,
    json: true
  });
}

return [{ json: { planId: plan?.id, weekNumber: output.weekNumber, year: output.year, mealCount: output.meals.length } }];

const data = $('Status OK?').first().json;
const output = data.output;
const planInfo = $input.first().json;

const dayEmojis = {
  1: '\ud83d\udfe2', // Monday - green
  2: '\ud83d\udfe1', // Tuesday - yellow
  3: '\ud83d\udfe0', // Wednesday - orange
  4: '\ud83d\udd35', // Thursday - blue
  5: '\ud83c\udf89', // Friday - party
  6: '\u2728',       // Saturday - sparkles
  7: '\u2615'        // Sunday - coffee
};

const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: `Ukeplan uke ${output.weekNumber}, ${output.year}`,
      emoji: true
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: output.weekSummary
    }
  },
  { type: 'divider' }
];

for (const meal of output.meals) {
  const emoji = dayEmojis[meal.dayOfWeek] || '\ud83c\udf7d\ufe0f';
  let mealText = `${emoji} *${meal.dayName}: ${meal.name}*\n${meal.description}`;
  if (meal.estimatedPrepMin) {
    mealText += `\n_ca ${meal.estimatedPrepMin} min_`;
  }
  if (meal.childTip) {
    mealText += `\n\ud83d\udc76 ${meal.childTip}`;
  }
  if (meal.batchNote) {
    mealText += `\n\ud83e\uddf1 ${meal.batchNote}`;
  }
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: mealText }
  });
}

blocks.push({ type: 'divider' });

// Nutrition & seasonal notes
const notesLines = [];
if (output.nutritionNotes) notesLines.push(`*Naering:* ${output.nutritionNotes}`);
if (output.seasonalHighlight) notesLines.push(`*Sesong:* ${output.seasonalHighlight}`);
if (output.traditionNote) notesLines.push(`*Tradisjon:* ${output.traditionNote}`);

if (notesLines.length > 0) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: notesLines.join('\n\n') }
  });
  blocks.push({ type: 'divider' });
}

// Shopping highlights
if (output.shoppingHighlights && output.shoppingHighlights.length > 0) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*Handleliste:*\n${output.shoppingHighlights.map(i => `\u2022 ${i}`).join('\n')}`
    }
  });
  blocks.push({ type: 'divider' });
}

// Emoji legend
blocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: '\ud83d\udc4d Godkjenn | \ud83d\udc4e Avvis | \ud83d\udd01 Ny plan | Run: ' + data.runId
    }
  ]
});

return [{ json: { blocks, planId: planInfo.planId, text: `Ukeplan uke ${output.weekNumber}` } }];

const config = $('Resolve Config').first().json;
const slackData = $input.first().json;

const channel = config.slackChannelHusmor || '#husmor';
const token = config.slackHusmorBotToken;

if (!token) {
  throw new Error('SLACK_HUSMOR_BOT_TOKEN is not configured');
}

const slackRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://slack.com/api/chat.postMessage',
  headers: {
    'Authorization': `Bearer ${token}`,
    'Content-Type': 'application/json'
  },
  body: {
    channel,
    blocks: slackData.blocks,
    text: slackData.text
  },
  json: true
});

if (!slackRes.ok) {
  throw new Error(`Slack error: ${slackRes.error}`);
}

// Save slack_message_ts back to weekly_plans
if (slackData.planId && slackRes.ts) {
  const supabaseUrl = config.supabaseUrl;
  const supabaseKey = config.supabaseKey;
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${supabaseUrl}/rest/v1/weekly_plans?id=eq.${slackData.planId}`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`,
      'Content-Type': 'application/json'
    },
    body: {
      slack_message_ts: slackRes.ts,
      slack_channel: slackRes.channel || channel
    },
    json: true
  });
}

return [{ json: { slackSent: true, ts: slackRes.ts, channel: slackRes.channel } }];
